CREATE   PROCEDURE [synapse_fo].[usp_Update_TAXTRANS]
AS
BEGIN
	
	UPDATE tgt SET
		tgt.[SinkCreatedOn]  =src.[SinkCreatedOn],
		tgt.[SinkModifiedOn]  =src.[SinkModifiedOn],
		tgt.[eurotriangulation]  =src.[eurotriangulation],
		tgt.[exempttax]  =src.[exempttax],
		tgt.[intracomvat]  =src.[intracomvat],
		tgt.[isoverunderpayment]  =src.[isoverunderpayment],
		tgt.[postponevat]  =src.[postponevat],
		tgt.[source]  =src.[source],
		tgt.[taxautogenerated]  =src.[taxautogenerated],
		tgt.[taxdirection]  =src.[taxdirection],
		tgt.[taxobligationcompany]  =src.[taxobligationcompany],
		tgt.[taxorigin]  =src.[taxorigin],
		tgt.[taxprintdetail]  =src.[taxprintdetail],
		tgt.[taxtype_mx]  =src.[taxtype_mx],
		tgt.[unrealizedtax]  =src.[unrealizedtax],
		tgt.[unrealizedtaxext]  =src.[unrealizedtaxext],
		tgt.[reversecharge_w] = src.[reversecharge_w],
		tgt.[reversechargeapplies_uk]  =src.[reversechargeapplies_uk],
		tgt.[taxaccounttype]  =src.[taxaccounttype],
		tgt.[skipledgerposting]  =src.[skipledgerposting],
		tgt.[sysdatastatecode]  =src.[sysdatastatecode],
		tgt.[currencycode]  =src.[currencycode],
		tgt.[exemptcode]  =src.[exemptcode],
		tgt.[headingtableid]  =src.[headingtableid],
		tgt.[inventtransid]  =src.[inventtransid],
		tgt.[invoiceid]  =src.[invoiceid],
		tgt.[journalnum]  =src.[journalnum],
		tgt.[printcode]  =src.[printcode],
		tgt.[realizeddate]  =src.[realizeddate],
		tgt.[sourcebaseamountcur]  =src.[sourcebaseamountcur],
		tgt.[sourcebaseamountcurregulated]  =src.[sourcebaseamountcurregulated],
		tgt.[sourcecurrencycode]  =src.[sourcecurrencycode],
		tgt.[sourcedocumentline]  =src.[sourcedocumentline],
		tgt.[sourcerecid]  =src.[sourcerecid],
		tgt.[sourceregulateamountcur]  =src.[sourceregulateamountcur],
		tgt.[sourcetableid]  =src.[sourcetableid],
		tgt.[sourcetaxamountcur]  =src.[sourcetaxamountcur],
		tgt.[statementid]  =src.[statementid],
		tgt.[taxamount]  =src.[taxamount],
		tgt.[taxamountcur]  =src.[taxamountcur],
		tgt.[taxamountrep]  =src.[taxamountrep],
		tgt.[taxbaseamount]  =src.[taxbaseamount],
		tgt.[taxbaseamountcur]  =src.[taxbaseamountcur],
		tgt.[taxbaseamountrep]  =src.[taxbaseamountrep],
		tgt.[taxbaseqty]  =src.[taxbaseqty],
		tgt.[taxbook]  =src.[taxbook],
		tgt.[taxbooksection]  =src.[taxbooksection],
		tgt.[taxcode]  =src.[taxcode],
		tgt.[taxgroup]  =src.[taxgroup],
		tgt.[taxincostprice]  =src.[taxincostprice],
		tgt.[taxincostpricecur]  =src.[taxincostpricecur],
		tgt.[taxincostpricerep]  =src.[taxincostpricerep],
		tgt.[taxincostpricemst]  =src.[taxincostpricemst],
		tgt.[taxincostpriceregulated]  =src.[taxincostpriceregulated],
		tgt.[taxitemgroup]  =src.[taxitemgroup],
		tgt.[taxjurisdictioncode]  =src.[taxjurisdictioncode],
		tgt.[taxperiod]  =src.[taxperiod],
		tgt.[taxrepcounter]  =src.[taxrepcounter],
		tgt.[taxtransrefrecid]  =src.[taxtransrefrecid],
		tgt.[taxvalue]  =src.[taxvalue],
		tgt.[transdate]  =src.[transdate],
		tgt.[voucher]  =src.[voucher],
		tgt.[taxid]  =src.[taxid],
		tgt.[vatexemptpct]  =src.[vatexemptpct],
		tgt.[partytaxid]  =src.[partytaxid],
		tgt.[origintaxtransrecid]  =src.[origintaxtransrecid],
		tgt.[exchratedifforigrecid]  =src.[exchratedifforigrecid],
		tgt.[nopostingsourceregulateamountcur]  =src.[nopostingsourceregulateamountcur],
		tgt.[nopostingtaxamount]  =src.[nopostingtaxamount],
		tgt.[nopostingtaxamountcur]  =src.[nopostingtaxamountcur],
		tgt.[nopostingtaxamountrep]  =src.[nopostingtaxamountrep],
		tgt.[reason]  =src.[reason],
		tgt.[reasoncomment]  =src.[reasoncomment],
		tgt.[modifieddatetime]  =src.[modifieddatetime],
		tgt.[modifiedby]  =src.[modifiedby],
		tgt.[createddatetime]  =src.[createddatetime],
		tgt.[createdby]  =src.[createdby],
		tgt.[modifiedtransactionid]  =src.[modifiedtransactionid],
		tgt.[createdtransactionid]  =src.[createdtransactionid],
		tgt.[createdon]  =src.[createdon],
		tgt.[modifiedon]  =src.[modifiedon]
	FROM [synapse_fo].[TAXTRANS] tgt
		INNER JOIN [staging_fo].[TAXTRANS] src
			ON tgt.[recid] = src.[recid]
			AND tgt.[dataareaid] = src.[dataareaid]

END
